fn extraction_entries() -> Vec<FixtureEntry> {
    let (bgra, _) = known_pixels();
    vec![
        FixtureEntry::new(MID, build_vtex(4, 2, 28, &bgra)),
        FixtureEntry::new(MID_TUNNELS, build_vtex(4, 2, 28, &bgra)),
        FixtureEntry::new(RAT_TUNNELS, build_vtex(4, 2, 28, &bgra)),
        FixtureEntry::new(HERO, build_vtex(4, 2, 28, &bgra)),
        FixtureEntry::new(HERO_TOPBAR, build_vtex(2, 2, 28, &bgra)),
        FixtureEntry::new(TOPBAR_MASK, build_vtex(2, 2, 28, &bgra)),
        FixtureEntry::new(TOPBAR_SVG, panorama_resource(b"<svg></svg>", 2)),
        FixtureEntry::new(HUD_STYLE, panorama_resource(b"@define X: #fff;", 3)),
        FixtureEntry::new(HEROES, kv3_resource(&encode_kv3(&hero_tree(), 0))),
        FixtureEntry::new(
            HERO_NAMES,
            b"\"lang\"\n{\n\t\"Tokens\"\n\t{\n\t\t\"hero_test:n\" \"Test Hero\"\n\t}\n}\n".to_vec(),
        ),
    ]
}

#[test]
fn vpk_round_trip_and_png() {
    let (bgra, rgba) = known_pixels();
    let fixture = build_fixture(
        &[FixtureEntry::new(HERO, build_vtex(4, 2, 28, &bgra))],
        &[],
    );

    let game = GameDir::new(&fixture.game).expect("game dir");
    let vpk = Vpk::open(&game, "pak01_dir.vpk").expect("open vpk");
    let entry = vpk.entry(HERO).expect("entry");
    assert_eq!(entry.size(), 80 + bgra.len() as u64);

    let bytes = vpk.read(HERO).expect("read entry");
    let texture = decode_vtex(&bytes).expect("decode texture");
    assert_eq!((texture.width, texture.height), (4, 2));
    assert_eq!(texture.rgba, rgba);

    let out = tempfile::tempdir().expect("out dir");
    let path = out.path().join("test.png");
    write_png(&path, texture.width, texture.height, &texture.rgba).expect("write png");
    let (width, height, decoded) = read_png(&path);
    assert_eq!((width, height), (4, 2));
    assert_eq!(decoded, rgba);
}

#[test]
fn corrupted_crc_is_detected() {
    let (bgra, _) = known_pixels();
    let mut entry = FixtureEntry::new(HERO, build_vtex(4, 2, 28, &bgra));
    entry.crc_override = Some(0);
    let fixture = build_fixture(&[entry], &[]);

    let game = GameDir::new(&fixture.game).expect("game dir");
    let vpk = Vpk::open(&game, "pak01_dir.vpk").expect("open vpk");
    match vpk.read(HERO) {
        Err(Error::CrcMismatch {
            expected, actual, ..
        }) => {
            assert_eq!(expected, 0);
            assert_ne!(actual, 0);
        }
        other => panic!("expected CrcMismatch, got {other:?}"),
    }
}

#[test]
fn path_traversal_is_refused() {
    let fixture = build_fixture(
        &[FixtureEntry::new("../evil.vtex_c", vec![0u8; 16])],
        &[],
    );

    let game = GameDir::new(&fixture.game).expect("game dir");
    let error = Vpk::open(&game, "pak01_dir.vpk").expect_err("traversal entry must fail");
    assert!(matches!(error, Error::UnsafePath(path) if path == "../evil.vtex_c"));
}

#[test]
fn non_allow_listed_path_is_refused() {
    let fixture = build_fixture(&[], &[]);
    std::fs::write(fixture.game.join("cfg.txt"), b"not for the extractor").expect("write file");

    let game = GameDir::new(&fixture.game).expect("game dir");
    let error = game.path("cfg.txt").expect_err("path must be refused");
    assert!(matches!(error, Error::PathNotAllowed(path) if path == "cfg.txt"));

    assert!(GameDir::is_allowed("steam.inf"));
    assert!(GameDir::is_allowed("pak01_dir.vpk"));
    assert!(GameDir::is_allowed("pak01_000.vpk"));
    assert!(GameDir::is_allowed("maps/dl_midtown.vpk"));
    assert!(GameDir::is_allowed(HERO_NAMES));
    assert!(!GameDir::is_allowed("account_12345678.stats"));
    assert!(!GameDir::is_allowed("cache_12345678.soc"));
    assert!(!GameDir::is_allowed("cfg/config.cfg"));
    assert!(!GameDir::is_allowed("pak01_1000.vpk"));
}

#[test]
fn unsupported_format_is_typed() {
    let fixture = build_fixture(
        &[FixtureEntry::new(HERO, build_vtex(2, 2, 99, &[0u8; 16]))],
        &[],
    );

    let game = GameDir::new(&fixture.game).expect("game dir");
    let vpk = Vpk::open(&game, "pak01_dir.vpk").expect("open vpk");
    let bytes = vpk.read(HERO).expect("read entry");
    assert!(matches!(
        decode_vtex(&bytes),
        Err(Error::UnsupportedFormat(99))
    ));
}

#[test]
fn size_mismatch_is_typed() {
    let fixture = build_fixture(
        &[FixtureEntry::new(HERO, build_vtex(2, 2, 28, &[0u8; 15]))],
        &[],
    );

    let game = GameDir::new(&fixture.game).expect("game dir");
    let vpk = Vpk::open(&game, "pak01_dir.vpk").expect("open vpk");
    let bytes = vpk.read(HERO).expect("read entry");
    assert!(matches!(
        decode_vtex(&bytes),
        Err(Error::TextureSizeMismatch {
            expected: 16,
            actual: 15
        })
    ));
}

#[test]
fn steam_inf_parses() {
    let info = SteamInfo::parse(
        "ClientVersion=6860\r\nSourceRevision=11211860\r\nVersionDate=Nov 05 2026\r\nVersionTime=16:40:40\r\n",
    )
    .expect("parse steam.inf");
    assert_eq!(info.client_version, 6860);
    assert_eq!(info.source_revision, 11211860);
    assert_eq!(info.version_date, "Nov 05 2026");
    assert_eq!(info.version_time, "16:40:40");
}

#[test]
fn output_inside_game_is_refused() {
    let fixture = build_fixture(&[], &[]);
    let out = fixture.game.join("out");
    match extract(&fixture.game, &out) {
        Err(Error::OutputInsideGame(_)) => {}
        other => panic!("expected OutputInsideGame, got {other:?}"),
    }
    assert!(!out.exists());
}

#[test]
fn output_inside_repo_is_refused() {
    let fixture = build_fixture(&[], &[]);
    let out = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("target")
        .join("extract-test-out");
    match extract(&fixture.game, &out) {
        Err(Error::OutputInsideRepo(_)) => {}
        other => panic!("expected OutputInsideRepo, got {other:?}"),
    }
    assert!(!out.exists());
}

#[test]
fn extract_writes_pack_and_blobs() {
    let fixture = build_fixture(
        &extraction_entries(),
        &[FixtureEntry::new(
            ENTITIES,
            kv3_resource(&encode_kv3(&entity_tree(), 0)),
        )],
    );
    let out = tempfile::tempdir().expect("out dir");

    let report = extract(&fixture.game, out.path()).expect("extract");
    assert_eq!(report.files.len(), 11);
    assert_eq!(report.blobs, 10);
    assert_eq!(report.sources, 11);

    for file in [
        "map/minimap_midtown_mid.png",
        "map/minimap_midtown_mid_tunnels.png",
        "map/minimap_midtown_rat_tunnels.png",
        "heroes/7.png",
        "topbar/heroes/7.png",
        "topbar/hero_image_mask_psd.png",
        "topbar/icon_ultimate.svg",
        "hud/hero_badge.vcss",
        "icons/base/minimap_midtown_mid_psd.png",
        "icons/base/minimap_midtown_mid_tunnels_psd.png",
        "icons/base/minimap_midtown_rat_tunnels_psd.png",
    ] {
        assert!(out.path().join(file).is_file(), "missing {file}");
    }

    let pack: serde_json::Value =
        serde_json::from_slice(&std::fs::read(out.path().join("pack.json")).expect("read pack"))
            .expect("parse pack");
    assert_eq!(pack["schema"].as_u64(), Some(3));
    assert_eq!(pack["extractor"]["name"].as_str(), Some("mapcro-extract"));
    assert_eq!(pack["game"]["client_version"].as_u64(), Some(1234));
    assert_eq!(pack["game"]["source_revision"].as_u64(), Some(5678));
    assert_eq!(pack["game"]["date"].as_str(), Some("Jan 02 2030"));
    assert_eq!(pack["sources"].as_array().expect("sources").len(), 11);
    assert_eq!(pack["blobs"].as_object().expect("blobs").len(), 10);

    let heroes = pack["heroes"].as_array().expect("heroes");
    assert_eq!(heroes.len(), 1);
    assert_eq!(heroes[0]["hero_id"].as_u64(), Some(7));
    assert_eq!(heroes[0]["class_name"].as_str(), Some("hero_test"));
    assert_eq!(heroes[0]["name"].as_str(), Some("Test Hero"));
    assert_eq!(heroes[0]["dev_state"].as_str(), Some("EHeroDevState_Release"));
    assert_eq!(heroes[0]["disabled"].as_bool(), Some(false));
    assert_eq!(heroes[0]["minimap_blob"].as_str(), Some("heroes/7"));
    assert_eq!(heroes[0]["topbar_blob"].as_str(), Some("topbar/heroes/7"));

    let entities = pack["entities"].as_array().expect("entities");
    assert_eq!(entities.len(), 2);
    assert_eq!(entities[0]["key"].as_str(), Some("patron:amber:lane1:1"));
    assert_eq!(entities[1]["key"].as_str(), Some("zipline:neutral:lane1:1"));
    assert_eq!(
        entities[1]["nodes"].as_array().expect("nodes").len(),
        1,
        "zipline node was not joined"
    );
    assert_eq!(
        pack["geometry_hash"].as_str().expect("geometry_hash").len(),
        64
    );

    assert_eq!(pack["icons"].as_array().expect("icons").len(), 3);
    assert_eq!(
        pack["icons_skipped"].as_array().expect("icons_skipped").len(),
        0
    );
    assert_eq!(
        pack["hud_sources"].as_array().expect("hud_sources").len(),
        1
    );
    assert_eq!(
        pack["hud_sources"][0]["key"].as_str(),
        Some("hud/hero_badge.vcss")
    );
}

/// Local-only check against a real install. Run with:
/// `MAPCRO_GAME_DIR=~/.local/share/Steam/steamapps/common/Deadlock/game/citadel \
///  nix develop -c cargo test -p mapcro-extract --test extract -- --ignored real_install`
#[test]
#[ignore = "reads the local Deadlock install; set MAPCRO_GAME_DIR to run"]
fn real_install() {
    let Some(game) = std::env::var_os("MAPCRO_GAME_DIR") else {
        eprintln!("MAPCRO_GAME_DIR is not set; skipping real-install test");
        return;
    };

    let out = Path::new("/tmp/mapcro-extract2-real");
    let _ = std::fs::remove_dir_all(out);
    let report = extract(Path::new(&game), out).expect("real extraction");

    assert!(out.join("map/minimap_midtown_mid.png").is_file());
    assert!(out.join("map/minimap_midtown_mid_tunnels.png").is_file());
    assert!(out.join("map/minimap_midtown_rat_tunnels.png").is_file());
    assert!(out.join("pack.json").is_file());

    let pack: serde_json::Value =
        serde_json::from_slice(&std::fs::read(out.join("pack.json")).expect("read pack"))
            .expect("parse pack");
    assert!(pack["heroes"].as_array().expect("heroes").len() > 40);
    assert!(pack["entities"].as_array().expect("entities").len() > 100);
    assert!(pack["icons"].as_array().expect("icons").len() > 50);
    assert_eq!(pack["hud_sources"].as_array().expect("hud").len(), 10);

    let topbar_blobs = pack["heroes"]
        .as_array()
        .expect("heroes")
        .iter()
        .filter(|hero| hero["topbar_blob"].is_string())
        .count();
    assert_eq!(topbar_blobs, 44, "expected 44 hero top-bar portraits");

    let fixed_topbar = pack["blobs"]
        .as_object()
        .expect("blobs")
        .keys()
        .filter(|key| key.starts_with("topbar/") && !key.starts_with("topbar/heroes/"))
        .count();
    assert_eq!(fixed_topbar, 10, "expected 10 fixed top-bar images");

    eprintln!(
        "real install: {} files, {} sources, {} blobs, pack at {}",
        report.files.len(),
        report.sources,
        report.blobs,
        report.pack.display()
    );
}
